<?php
require_once __DIR__.'/../config/db.php'; require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../services/requestService.php'; require_once __DIR__.'/../repositories/userPDO.php';
$pdo=openDatabase(); $admin=requireLogin($pdo); requireRole($admin,['Administrator']);
$id=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT); if(!$id||$id<1){http_response_code(400);exit('Invalid user ID');}
$u=findUserById($pdo,$id); if(!$u){http_response_code(404);exit('User not found');}
$counts=$pdo->prepare('SELECT COUNT(*) FROM students s JOIN tutoring_requests r ON r.student_id=s.student_id WHERE s.user_id=?');$counts->execute([$id]);$requestCount=(int)$counts->fetchColumn();
require __DIR__.'/../includes/header.php'; require __DIR__.'/../includes/nav.php'; ?>
<main class="container py-4"><h1>Manage Account</h1><dl class="row"><dt class="col-sm-3">Name</dt><dd class="col-sm-9"><?=escapeHtml($u['full_name'])?></dd><dt class="col-sm-3">Email</dt><dd class="col-sm-9"><?=escapeHtml($u['email'])?></dd><dt class="col-sm-3">Role</dt><dd class="col-sm-9"><?=escapeHtml($u['role'])?></dd><dt class="col-sm-3">Status</dt><dd class="col-sm-9"><?=escapeHtml($u['status'])?></dd><dt class="col-sm-3">Related requests</dt><dd class="col-sm-9"><?=$requestCount?></dd></dl>
<section class="card card-body mb-3"><h2 class="h5">Update role</h2><form method="post" action="admin-user-action.php"><input type="hidden" name="csrf_token" value="<?=escapeHtml(csrfToken())?>"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="action" value="role"><select class="form-select mb-2" name="role"><?php foreach(['Student','Tutor','Administrator'] as $r):?><option <?=$u['role']===$r?'selected':''?>><?=$r?></option><?php endforeach;?></select><button class="btn btn-primary">Save Role</button></form></section>
<section class="card card-body mb-3"><h2 class="h5">Account status</h2><form method="post" action="admin-user-action.php"><input type="hidden" name="csrf_token" value="<?=escapeHtml(csrfToken())?>"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="action" value="status"><select class="form-select mb-2" name="status"><?php foreach(['Active','Inactive'] as $st):?><option <?=$u['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn btn-primary">Confirm Status</button></form></section>
